    opp = ao if (not _isnan(sd) and sd >= 0) else ho
    lead = ho if (not _isnan(sd) and sd > 0) else (ao if (not _isnan(sd) and sd < 0) else np.nan)
    lose = ao if (not _isnan(sd) and sd > 0) else (ho if (not _isnan(sd) and sd < 0) else np.nan)
    line = tick.get('total_goals_handicap', tick.get('total_points_handicap', np.nan))
